export const QUESTION_KEYS=Object.keys(QUESTIONS);
export const emptyRecord=()=>({encounters:0,firstCorrect:0,mistakes:0,correct:0,needsReview:false,latest:'Not practiced'});
export function recordQuestion(progress,key,correct,attempt){const id=QUESTIONS[key].id;progress.items??={};if(progress.stats[id].needsReview&&!QUESTION_KEYS.some(k=>QUESTIONS[k].id===id&&progress.items[k]?.needsReview))progress.items[id]={...progress.stats[id]};record(progress.stats,id,correct,attempt);progress.items[key]??=emptyRecord();record(progress.items,key,correct,attempt);progress.stats[id].needsReview=QUESTION_KEYS.some(k=>QUESTIONS[k].id===id&&progress.items[k]?.needsReview);}
export function practiceKeys(progress,missed=false){if(!missed)return [...QUESTION_KEYS];const keys=QUESTION_KEYS.filter(k=>progress.items?.[k]?.needsReview);for(const c of CONCEPTS)if(progress.stats[c.id].needsReview&&!keys.some(k=>QUESTIONS[k].id===c.id))keys.push(c.id);return [...new Set(keys)];}
